INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('35e19d2e-d124-4cad-bae7-91c6c27ed006', 'Rolex Oyster Perpetual Datejust – Burgundy Gold Edition', 'Elevate your style with the Rolex Oyster Perpetual Datejust Burgundy Gold Edition. Featuring a striking burgundy sunburst dial, elegant two-tone stainless steel and gold bracelet, and precision craftsmanship, this iconic timepiece blends timeless luxury with everyday sophistication. Perfect for formal occasions and premium everyday wear.', 3199, 5000, 'Men''s Watches', '/images/sswp3s3mqv_1785476778967.png', '["/images/sswp3s3mqv_1785476778967.png"]', 10, 'rgba(175, 30, 50, 0.65)', 1) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('8a8c6d7d-38b6-481c-bddf-8d4e4bfa1ff2', 'Emerald Crystal Prestige', 'Make a bold statement with the Emerald Prestige Stainless Steel Watch, featuring a striking green crystal bezel, textured black dial, and premium stainless steel bracelet. Designed for those who appreciate modern luxury, this timepiece blends refined craftsmanship with everyday sophistication. Perfect for both formal occasions and daily wear', 4499, 8500, 'Men''s Watches', '/images/wwsfoz8tuon_1785483645448.png', '["/images/wwsfoz8tuon_1785483645448.png","/images/seeh6k6acof_1786088507207.jpeg","/images/3q04d4ocw6f_1786088525440.jpeg"]', 10, 'rgba(16, 125, 75, 0.65)', 4) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('1dd2997c-3ac8-4ed4-bde6-8f459a537281', 'Hublot Geneva Skeleton Tourbillon – Silver Grey Edition', 'Experience modern Swiss-inspired craftsmanship with the Hublot Geneva Skeleton Tourbillon – Silver Grey Edition. Designed with a striking open-work skeleton dial, this luxury timepiece showcases the intricate mechanical movement through a crystal-clear sapphire-style display. The brushed silver-tone case pairs perfectly with the premium grey leather strap, creating a refined look for any occasion. Precision detailing, premium materials, and bold engineering make this watch an exceptional statement of style and sophistication.', 2499, 4500, 'Men''s Watches', '/images/ifttr85romm_1785490457393.png', '["/images/ifttr85romm_1785490457393.png","/images/q2614gvlp2s_1786089381500.jpeg","/images/jzailkvoj4i_1786089390981.jpeg"]', 10, 'rgba(75, 85, 105, 0.60)', 8) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('e7b3fcd9-4536-49d9-906a-81d246763f8c', 'Rolex Oyster perpetual', 'Experience timeless elegance with the WearOrvano Royal Blue Prestige. Crafted with a premium stainless steel case, a striking blue dial, and a polished bracelet, this watch delivers the perfect balance of luxury and everyday sophistication. Designed for those who appreciate exceptional style and lasting quality.', 3199, 5000, 'Men''s Watches', '/images/qphffzhjwm_1785475928426.png', '["/images/qphffzhjwm_1785475928426.png","/images/pceqwbcctis_1786088094501.jpeg","/images/c0bd22u8lbq_1786088107099.jpeg"]', 10, 'rgba(35, 95, 175, 0.55)', 2) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('6e7d2bff-75a7-4e98-a86d-ba553e8f9bda', 'Hublot Geneva Classic Arabic Automatic – Black Edition', 'Experience timeless elegance with the Hublot Geneva Classic Arabic Automatic – Black Edition. Featuring a striking white dial with distinctive Arabic numeral hour markers, a premium matte black case, and a textured black leather strap, this watch blends modern luxury with classic craftsmanship. The automatic movement, sapphire crystal-inspired finish, and refined stainless-steel details make it the perfect choice for both formal occasions and everyday wear.', 2399, 4500, 'Men''s Watches', '/images/yang2mmbyv_1785490206651.png', '["/images/yang2mmbyv_1785490206651.png","/images/dlwxklctx8_1786169740477.png","/images/tp9bdwfmljn_1786169751253.png"]', 10, 'rgba(75, 85, 105, 0.60)', 7) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('173a9c17-49ab-4d82-b10d-94279a19047c', 'Lamborghini Carbon Phantom Automatic', 'Inspired by Lamborghini''s bold design language, the Carbon Phantom Automatic combines a striking skeleton dial with a stealth-black case and premium rubber strap. Precision-crafted for those who appreciate modern luxury, performance, and unmistakable style. Built to make a statement on every wrist.', 3499, 7500, 'Men''s Watches', '/images/q4jvjffrj3_1785480282555.png', '["/images/q4jvjffrj3_1785480282555.png","/images/hytuwxxt02m_1786087841420.jpeg","/images/35ttxhgivhw_1786088004949.jpeg"]', 10, 'rgba(195, 145, 35, 0.65)', 1) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('164a5942-8583-456c-8181-28177c7c30b0', 'Rolex Yacht-Master Black Edition', 'Elevate your style with the Rolex Yacht-Master Black Edition, featuring a bold black dial, premium black bezel, and comfortable rubber strap. Designed with luminous hour markers, a magnified date display, and a durable stainless-steel case, this luxury-inspired timepiece delivers a sophisticated look for both everyday wear and special occasions.', 2999, 6000, 'Men''s Watches', '/images/oxn2fcqz5xd_1785492058609.png', '["/images/oxn2fcqz5xd_1785492058609.png","/images/pvp8j1ouzr_1786169601008.png","/images/x7f2m2i08io_1786169608119.png"]', 10, 'rgba(75, 85, 105, 0.60)', 11) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('b38c26c0-f3e8-4d9c-835f-4303a7c6dab5', 'Hublot Classic Fusion Chronograph Silver Stainless Steel Watch', 'Elevate your style with the Hublot Classic Fusion Chronograph, a luxury-inspired timepiece featuring a bold silver stainless steel case, elegant integrated bracelet, and a sophisticated black chronograph dial. Designed with precision-inspired craftsmanship, it showcases luminous hands, detailed sub-dials, a convenient date display, and a premium brushed-metal finish. Combining modern aesthetics with timeless elegance, this watch is the perfect accessory for business, formal occasions, or everyday luxury.
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('9debd50c-ebb0-4a61-8bac-8075690e2037', 'Hublot Classic Fusion Tourbillon Skeleton – Blue Edition', 'Elevate your style with the Hublot Classic Fusion Tourbillon Skeleton – Blue Edition. Featuring a striking open-worked skeleton dial, premium silver-tone stainless steel case, and an elegant deep blue rubber strap, this timepiece blends modern engineering with timeless luxury. The intricate visible movement, bold design, and exceptional craftsmanship make it the perfect statement watch for business, formal events, or everyday sophistication.', 2399, 4000, 'Men''s Watches', '/images/gw4l7uth92i_1785492478678.png', '["/images/gw4l7uth92i_1785492478678.png","/images/e4f80x416ya_1786169525559.png","/images/5bdohw68pu_1786169533971.png"]', 10, 'rgba(35, 95, 175, 0.55)', 13) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('a9d3b171-2965-4fd1-be56-8ec141c753b7', 'Patek Philippe Nautilus Green Dial – Classic Edition', 'Make a bold statement with the Patek Philippe Nautilus Green Dial – Classic Edition, a perfect blend of timeless elegance and contemporary luxury. Featuring a striking emerald green textured dial, a polished silver-tone stainless steel case, and a premium green crocodile-pattern leather strap, this watch delivers refined style for every occasion. The iconic rounded-square bezel, date display, and precision quartz movement create a sophisticated timepiece designed for both formal and everyday wear', 2899, 4000, 'Men''s Watches', '/images/6m9uxvtzb24_1785491777057.png', '["/images/6m9uxvtzb24_1785491777057.png","/images/zlz9krn92r_1786088946772.jpeg","/images/fpw8u8w33tf_1786089026639.jpeg"]', 10, 'rgba(16, 125, 75, 0.65)', 10) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('3d21bb2f-767f-4019-b891-d14ac7bb6ff2', 'RM Transparent Skeleton Automatic Watch', 'Experience bold luxury with the RM Transparent Skeleton Automatic Watch. Featuring a striking transparent tonneau-shaped case, an intricate skeleton dial that showcases the mechanical movement, and a durable black rubber strap, this timepiece blends modern engineering with premium style. Designed for those who appreciate high-end aesthetics, it offers exceptional craftsmanship, eye-catching details, and a comfortable fit for everyday wear or special occasions. A perfect statement piece for watch enthusiasts seeking a sophisticated and contemporary look.', 2999, 5000, 'Men''s Watches', '/images/cf8g77lreq_1785492703486.png', '["/images/cf8g77lreq_1785492703486.png","/images/q1ztmnzlei_1786169476292.png","/images/ljgwuhnkky_1786169485848.png"]', 10, 'rgba(70, 125, 185, 0.50)', 14) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('2d2102d2-0bb3-4277-90e1-932d1cf80901', 'Citizen Gold Quartz Day-Date Watch – Luxury Gold Dial Edition', 'Refined, elegant, and designed to impress, this Citizen Gold Quartz Day-Date Watch features a radiant gold sunburst dial housed in a polished gold-tone stainless steel case and matching bracelet. Crystal-style hour markers, Roman numeral accents, and a convenient day-date display create a sophisticated look that transitions effortlessly from business meetings to formal occasions. Powered by reliable quartz movement, this timeless timepiece offers precision, comfort, and everyday luxury in one elegant design.', 2999, 5000, 'Men''s Watches', '/images/kbfod60xdu_1785563877378.png', '["/images/kbfod60xdu_1785563877378.png","/images/ujxxs74f6u_1786169279789.png","/images/1zj4e39wwp7_1786169286116.png"]', 10, 'rgba(195, 145, 35, 0.65)', 20) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('3edc3d06-50a4-4fab-bec2-ba088b168df4', 'Rolex Yacht-Master Rose Gold Black Dial Rubber Strap Watch', 'Make a bold statement with this Rolex Yacht-Master inspired luxury timepiece, featuring a striking black dial paired with a polished rose gold-tone case and bezel. The sporty black rubber strap delivers exceptional comfort while complementing the premium aesthetic. A magnified date display, luminous hour markers, and precision-inspired detailing create a sophisticated look suitable for both everyday wear and special occasions. Crafted with a durable stainless steel case and a scratch-resistant crystal appearance, this watch combines timeless elegance with modern performance.', 2999, 6000, 'Men''s Watches', '/images/xgvnhy7cut_1785563280984.png', '["/images/xgvnhy7cut_1785563280984.png","/images/2q2yrp7gt3h_1786169335693.png","/images/4xs095dsx3c_1786169345448.png"]', 10, 'rgba(75, 85, 105, 0.60)', 18) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('7b31ca8d-7d5e-4d11-b71c-992ac12e23d3', 'Rolex Day-Date Inspired Burgundy Diamond Dial Stainless Steel Luxury Watch', 'Elevate your everyday style with this Rolex Day-Date inspired luxury timepiece, featuring a captivating burgundy sunburst dial accented with sparkling crystal hour markers for a refined and sophisticated look. The polished stainless steel case and Jubilee-style bracelet deliver timeless elegance, while the magnified date window adds both practicality and iconic appeal.
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('573929c1-6a3a-463e-a4aa-f1355411dac7', 'Rolex Oyster Perpetual Land-Dweller Green Honeycomb Two-Tone Watch', 'Experience timeless luxury with the Rolex Oyster Perpetual Land-Dweller, featuring a striking green honeycomb-pattern dial, elegant fluted gold bezel, and sophisticated two-tone stainless steel and gold bracelet. Crafted with precision-inspired detailing, luminous hands and markers, a magnified date display, and a premium polished finish, this watch delivers an iconic look for both formal and everyday wear. A perfect statement piece that blends classic craftsmanship with modern elegance.', 3199, 5000, 'Men''s Watches', '/images/e5mxj48r6yq_1785562920503.png', '["/images/e5mxj48r6yq_1785562920503.png","/images/3tmssxbnyoe_1786169443925.png","/images/z4a522f3p9_1786169450504.png"]', 10, 'rgba(16, 125, 75, 0.65)', 15) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('41828e14-b6f7-40f2-8161-1daa378b06ad', 'RADO Integral Automatic – Silver Ceramic Edition', 'Experience timeless sophistication with the RADO Integral Automatic, a refined timepiece that blends minimalist Swiss-inspired design with modern elegance. Featuring a sleek silver-tone square case, a clean silver dial, and an integrated bracelet, this watch offers a contemporary look that transitions effortlessly from business attire to everyday wear. The automatic movement, date display, polished hands, and understated hour markers enhance its premium appeal, while the scratch-resistant crystal appearance and precision-crafted finish ensure lasting style and durability.', 2999, 5000, 'Men''s Watches', '/images/bpbysfac64d_1785564223470.png', '["/images/bpbysfac64d_1785564223470.png","/images/3nt16y3pp2w_1786169212568.png","/images/3e2w7nek18q_1786169219976.png"]', 10, 'rgba(75, 85, 105, 0.60)', 22) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('800f7a57-aef7-4543-be71-5765685a6f4c', 'Midnight Luxe Crystal Digital Watch', 'A stunning crystal-studded digital watch crafted to make every moment shine. Featuring a sleek black square display with vibrant green LED digits, a premium black metal finish, and a bracelet fully embellished with sparkling stones, this timepiece blends modern technology with luxury-inspired elegance. Lightweight, eye-catching, and perfect for both casual and formal wear, it''s designed for those who love bold style and everyday sophistication.', 1299, 1999.99, 'Women''s Watches', '/images/1ys3h1h11ini_1785565667556.png', '["/images/1ys3h1h11ini_1785565667556.png","/images/1lpgiwaxe3b_1786168933002.png","/images/uwd9stvjams_1786168937835.png"]', 10, 'rgba(16, 125, 75, 0.65)', 27) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('4a4a8a25-1aeb-4ba5-80fa-3b017947fd7b', 'Casal Rose Gold Women''s Quartz Watch', 'Add timeless elegance to your everyday style with the Casal Rose Gold Women''s Quartz Watch. Designed with a luxurious rose gold finish, this beautiful timepiece features a textured bezel, a clean champagne dial, and a stylish geometric-link bracelet that offers both comfort and sophistication. Its reliable quartz movement ensures accurate timekeeping, making it perfect for daily wear, office outfits, casual occasions, and special events. A graceful accessory that blends fashion with functionality.', 1499, 2000, 'Women''s Watches', '/images/7nlj26a95ks_1785566182295.png', '["/images/7nlj26a95ks_1785566182295.png","/images/osz0dp83u7_1786168886038.png","/images/pdj3ukaci2_1786168895024.png"]', 10, 'rgba(185, 80, 115, 0.65)', 29) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('d46e42a0-a225-4bbd-98de-63a6aacfe6bf', 'Moonston Rose Gold Crystal Quartz Watch', 'Elevate your everyday style with the Moonston Rose Gold Crystal Quartz Watch. Designed with a radiant rose gold finish, a shimmering crystal-studded bezel, and an elegant sunburst dial featuring crystal hour markers, this timepiece blends timeless sophistication with modern luxury. Powered by a precise quartz movement and finished with a polished stainless steel bracelet, it offers reliable performance, lasting comfort, and effortless elegance—perfect for daily wear, special occasions, or as a thoughtful gift.', 1999, 3500, 'Women''s Watches', '/images/mcmz5curgjo_1785566166660.png', '["/images/mcmz5curgjo_1785566166660.png","/images/mkz07s5bkjs_1786168913244.png","/images/chjibqu5r09_1786168919956.png"]', 10, 'rgba(175, 30, 50, 0.65)', 28) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('d0d2d949-0f4d-43de-87ce-c24f4144a6dc', 'Rolex Oyster Perpetual Blue Dial Stainless Steel Watch', 'Experience timeless elegance with this Rolex Oyster Perpetual-inspired stainless steel watch, featuring the exact blue sunburst dial design shown in the reference image. Crafted with a polished silver-tone case and matching stainless steel bracelet, it offers a refined luxury aesthetic suitable for both formal and everyday wear. The minimalist dial is enhanced with crystal-style hour markers, silver hands, the iconic crown logo, and premium text detailing, creating a sophisticated look. Built with a durable bracelet, precision quartz movement, and a comfortable clasp, this watch combines classic Swiss-inspired styling with modern versatility.', 1999, 4000, 'Men''s Watches', '/images/497qze9s8lv_1786169030385.png', '["/images/497qze9s8lv_1786169030385.png","/images/v1q2h94z8_1786169042660.png","/images/44k9g0shsx8_1786169048393.png"]', 10, 'rgba(185, 80, 115, 0.65)', 26) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('52969c24-afd4-489c-8463-5990942ec705', 'Patek Philippe Nautilus Green Dial Stainless Steel Automatic Watch', 'Elevate your style with the iconic Patek Philippe Nautilus Green Dial Automatic Watch. Featuring a distinctive horizontally embossed green dial, polished silver-tone hands and baton hour markers, a date display at 3 o''clock, and an integrated stainless steel bracelet with brushed and polished finishes, this timepiece blends timeless elegance with modern luxury. Powered by an automatic movement and protected by a scratch-resistant sapphire crystal, it delivers exceptional precision, comfort, and sophistication—perfect for both daily wear and special occasions.', 2999, 6000, 'Men''s Watches', '/images/tzevjnqhbii_1785565065483.png', '["/images/tzevjnqhbii_1785565065483.png","/images/3ovyb9qd0c9_1786169070678.png","/images/ozbo50qrep_1786169079926.png"]', 10, 'rgba(16, 125, 75, 0.65)', 25) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('601a372b-514d-4622-bf86-a2c5c78a2522', 'Light Blue Washed Baggy Jeans', 'Light blue washed baggy jeans featuring a relaxed, wide-leg fit and a clean 5-pocket design. The subtle washed finish gives them a modern vintage look, while the comfortable baggy silhouette makes them perfect for casual and streetwear outfits.', 1999, 3000, 'Pants', '/images/mer79wr6axp_1787295189200.webp', '["/images/mer79wr6axp_1787295189200.webp","/images/59mva2xp78u_1787295190839.webp"]', 10, 'rgba(35, 95, 175, 0.55)', 39) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('53b498c3-8dfa-4533-b161-fd14c2132491', 'Dark Blue Cargo Baggy Jeans', 'Premium dark blue denim cargo baggy jeans with a loose, wide-leg fit. Features multiple functional cargo pockets on the sides, classic front and back pockets, belt loops, button closure, and a subtle washed finish. Perfect for a modern streetwear and casual look.', 1999, 3000, 'Pants', '/images/4zu4knaxz0f_1787295431036.webp', '["/images/4zu4knaxz0f_1787295431036.webp","/images/p9wkv043mo8_1787295432412.webp"]', 10, 'rgba(75, 85, 105, 0.60)', 42) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('9853743a-29af-42d2-a56d-69336b06db5e', 'Dark Blue Baggy Jeans', 'Premium dark blue denim baggy jeans with a loose, relaxed fit and wide-leg silhouette. Features a classic 5-pocket design, subtle washed finish, durable stitching, belt loops, and button closure. Perfect for a modern streetwear and casual look.', 1999, 3000, 'Pants', '/images/2emkl0kkel_1787295344994.webp', '["/images/2emkl0kkel_1787295344994.webp","/images/0s7tixgytve_1787295346419.webp"]', 10, 'rgba(70, 125, 185, 0.50)', 41) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('11b1c87b-f252-4daf-a8ae-687767cd7a02', 'Moonston Elegant Duo Women''s Watch Set – Gold & Black Edition', 'Elevate your style with the Moonston Elegant Duo Women''s Watch Set, featuring two stunning timepieces in timeless Gold and sophisticated Black finishes. Designed with sparkling crystal-studded bezels, elegant decorative bracelet links, and precision quartz movement, this premium duo offers the perfect blend of luxury and everyday elegance.
