INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('d840cc32-722b-45a3-a37f-37854240906e', 'MIRA Rose Gold Pink Crystal Bracelet Watch for Women', 'Elevate your style with the Moonston Luxe Blossom Duo, a beautifully curated set featuring two elegant women''s watches in Rose Gold and Silver finishes. Designed with sparkling crystal-studded bezels, delicate floral bracelet accents, and premium craftsmanship, this luxury pair complements every outfit—from everyday elegance to special occasions.
