INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('2744bf49-586f-4540-a79e-f8ee26b8084c', 'Dark Blue Classic Straight-Leg Jeans Description:', 'Premium dark blue denim jeans featuring a classic straight-leg fit, 5-pocket design, and contrasting stitch detailing. Clean, timeless look with a structured silhouette, perfect for casual, everyday and smart-casual outfits.', 1999, 3000, 'Pants', '/images/dl5n27h080q_1787293863466.webp', '["/images/dl5n27h080q_1787293863466.webp","/images/5rb7lhra3u4_1787293870201.webp"]', 10, 'rgba(35, 95, 175, 0.55)', 36) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('d2b31c5d-906b-4bd2-8535-f60cef0ace02', 'Moonston Luxe Blossom Duo – Rose Gold & Silver Women''s Watch Set', 'Elevate your style with the Moonston Luxe Blossom Duo, a beautifully curated set featuring two elegant women''s watches in Rose Gold and Silver finishes. Designed with sparkling crystal-studded bezels, delicate floral bracelet accents, and premium craftsmanship, this luxury pair complements every outfit—from everyday elegance to special occasions.
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('8c741808-c1cd-4fa2-a8fb-48cf6bf35a61', 'Rustet Heritage Brown Leather Watch', 'Elevate your everyday style with the Rustet Heritage Brown Leather Watch, a perfect blend of classic elegance and modern craftsmanship. Featuring a rich sunburst brown dial, premium genuine leather strap, polished stainless steel case, and a distinctive contemporary dial layout, this timepiece delivers a refined look for both casual and formal occasions.
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('6299f351-2cea-4395-935e-c5be17ff94df', 'Patek Philippe Nautilus Stainless Steel Date Watch', 'Elevate your style with the iconic Patek Philippe Nautilus Stainless Steel Date Watch, a masterpiece of refined craftsmanship and timeless elegance. Featuring the signature rounded-octagonal bezel, an integrated stainless steel bracelet, and a sophisticated horizontal-textured black dial, this luxury timepiece is designed for those who appreciate precision and prestige. The luminous hands and hour markers ensure excellent readability, while the convenient date display at 3 o''clock adds everyday practicality. Finished with premium brushed and polished steel surfaces, this watch delivers a perfect balance of sportiness and sophistication for business, formal, and daily wear.', 2999, 6000, 'Men''s Watches', '/images/uvx8bp7ff_1785564576155.png', '["/images/uvx8bp7ff_1785564576155.png","/images/0nzl5lefl8t_1786169132551.png","/images/fl30u7cduew_1786169140706.png"]', 10, 'rgba(75, 85, 105, 0.60)', 24) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('7b87a92c-aa70-416e-b64b-0094c47ce8ab', 'RADO Black Automatic Ceramic Edition', 'Experience timeless sophistication with the RADO Black Automatic Ceramic Edition. Designed with a sleek square case and a deep black minimalist dial, this watch combines modern aesthetics with premium craftsmanship. The automatic movement eliminates the need for batteries, while the scratch-resistant ceramic-inspired bracelet and sapphire-style crystal deliver exceptional durability and a luxurious finish. Featuring elegant silver-tone hands, subtle diamond-style hour markers, and a practical date display, this timepiece is perfect for both formal occasions and everyday wear.', 2999, 5000, 'Men''s Watches', '/images/rh6wdz1fopd_1785564414327.png', '["/images/rh6wdz1fopd_1785564414327.png","/images/33sijsp3fx8_1786169181815.png","/images/ziymolu29a_1786169187094.png"]', 10, 'rgba(75, 85, 105, 0.60)', 23) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('7bb95472-c489-4944-b520-8d81bb1de9e9', 'Rolex Datejust Silver Dial Stainless Steel Luxury Watch', 'Timeless sophistication meets everyday versatility with this Rolex Datejust-inspired luxury watch. Featuring a radiant silver sunburst dial, polished stainless steel case, and an elegant Jubilee-style bracelet, this timepiece delivers a refined look for any occasion. Diamond-style hour markers, a magnified date display, and precision-inspired craftsmanship enhance its premium appeal. Designed for those who appreciate classic elegance and reliable performance, this watch is the perfect addition to both formal and casual wardrobes.', 3199, 5000, 'Men''s Watches', '/images/zynv75eewz9_1785564037263.png', '["/images/zynv75eewz9_1785564037263.png","/images/jhf2k586acb_1786169244757.png","/images/rmq4m37eeea_1786169254264.png"]', 10, 'rgba(75, 85, 105, 0.60)', 21) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('13abc077-2bf2-4451-8ef4-290426f7146e', 'Classic Light Blue Straight-Fit Jeans', 'Classic light blue denim jeans with a clean straight-fit design. Features a traditional 5-pocket style, button-fly closure, subtle faded wash, durable denim fabric, and a timeless look suitable for everyday casual wear.', 1999, 3000, 'Pants', '/images/eu1aprm4azt_1787295303790.webp', '["/images/eu1aprm4azt_1787295303790.webp","/images/z2weeo6sl2g_1787295305217.webp"]', 10, 'rgba(35, 95, 175, 0.55)', 40) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('a698f496-6643-4edc-a2b1-1d75055e2f8a', 'Citizen Quartz Silver Day-Date Stainless Steel Watch', 'Elevate your everyday style with the Citizen Quartz Silver Day-Date Watch, crafted with a sleek stainless steel case and matching bracelet for a timeless, sophisticated look. Featuring a refined silver sunburst dial, luminous hands, crystal-accented hour markers, and a convenient day-date display, this watch delivers both elegance and practicality. Powered by a reliable quartz movement, it offers accurate timekeeping with minimal maintenance. Its polished finish and versatile design make it the perfect accessory for business, formal occasions, or daily wear.', 2999, 5000, 'Men''s Watches', '/images/roh0p4xydu_1785563097935.png', '["/images/roh0p4xydu_1785563097935.png","/images/24x0gfnm9ub_1786169371140.png","/images/ug9pbfef0he_1786169380233.png"]', 10, 'rgba(195, 145, 35, 0.65)', 17) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
