INSERT INTO products (id, name, description, price, original_price, category, image_url, images, stock_quantity, glow_color, display_order) VALUES ('6384321f-bcd4-4ab9-a752-476e69910155', 'Hublot Classic Fusion Chronograph – Silver Black Edition', 'Experience timeless luxury with this Hublot Classic Fusion Chronograph, featuring a premium silver-tone stainless steel case, sophisticated skeleton-inspired black dial, and a comfortable black leather strap. Designed with precision detailing, chronograph functionality, and a sleek modern aesthetic, this watch delivers the perfect balance of elegance and performance. Ideal for business, formal occasions, or everyday luxury styling.', 2399, 4000, 'Men''s Watches', '/images/rbt850rphn_1785492282754.png', '["/images/rbt850rphn_1785492282754.png","/images/zt2n5ist4o_1786169562029.png","/images/3rbbuv31d53_1786169570360.png"]', 10, 'rgba(75, 85, 105, 0.60)', 12) ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), image_url=VALUES(image_url), images=VALUES(images);
